TLM.f("Sancti/04-02",{"officium":"S. Francisci de Paula Confessoris","rule":["vide C5b;","Gloria"],"fallback":"Commune/C5b","from":{"Introitus":"Commune/C5b","Graduale":"Commune/C5b","GradualeP":"Commune/C5b","Tractus":"Commune/C5b","Evangelium":"Commune/C5b","Offertorium":"Commune/C5b","Communio":"Commune/C5b"},"sections":{"Introitus":[{"k":"ref","la":"Ps 91:13-14"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Justus ut palma florébit: sicut cedrus Líbani multiplicábitur: plantátus in domo Dómini: in átriis domus Dei nostri."}],"Oratio":[{"k":"text","la":"Deus, humílium celsitúdo, qui beátum Francíscum Confessórem Sanctórum tuórum glória sublimásti: tríbue, quǽsumus; ut, ejus méritis et imitatióne, promíssa humílibus præmia felíciter consequámur."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Philippénses"},{"k":"ref","la":"Philipp 3:7-12"},{"k":"text","la":"Fratres: Quæ mihi fuérunt lucra, hæc arbitrátus sum propter Christum detriménta. Verúmtamen exístimo ómnia detriméntum esse propter eminéntem sciéntiam Jesu Christi, Dómini mei: propter quem ómnia detriméntum feci et árbitror ut stércora, ut Christum lucrifáciam et invéniar in illo, non habens meam justítiam, quæ ex lege est, sed illam, quæ ex fide est Christi Jesu: quæ ex Deo est justítia in fide, ad cognoscéndum illum, et virtútem resurrectiónis ejus, et societátem passiónum illíus: configurátus morti ejus: si quo modo occúrram ad resurrectiónem, quæ est ex mórtuis: non quod jam accéperim aut jam perféctus sim: sequor autem, si quo modo comprehéndam, in quo et comprehénsus sum a Christo Jesu."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja"},{"k":"ref","la":"Ps 111:1"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis. Allelúja"},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 12:32-34"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Nolíte timére, pusíllus grex, quia complácuit Patri vestro dare vobis regnum. Véndite quæ possidétis, et date eleemósynam. Fácite vobis sácculos, qui non veteráscunt, thesáurum non deficiéntem in cœlis: quo fur non apprópiat, neque tínea corrúmpit. Ubi enim thesáurus vester est, ibi et cor vestrum erit."}],"Offertorium":[{"k":"ref","la":"Ps 20:2-3"},{"k":"text","la":"In virtúte tua, Dómine, lætábitur justus, et super salutáre tuum exsultábit veheménter: desidérium ánimæ ejus tribuísti ei. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Hæc dona devótæ plebis, Dómine, quibus tua cumulámus altária, beáti Francísci méritis tibi grata nobísque salutária, te miseránte, reddántur."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 19:28-29"},{"k":"text","la":"Amen, dico vobis: quod vos, qui reliquístis ómnia et secúti estis me, céntuplum accipiétis, et vitam ætérnam possidébitis. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Sumpta, Dómine, sacraménta cœléstia: beáto Francísco Confessóre tuo intercedénte, precámur; ut et temporális vitæ subsídia nobis cónferant et ætérnæ."},{"k":"macro","name":"Per Dominum"}]},"hr":{"364ef4629d4ae954":{"kn":"Bože, uzvišenje poniznih, koji si blaženoga Franju, priznavaoca, uzdigao do slave svetih Tvojih, podaj, molimo, da njegovim zaslugama i nasljedovanjem sretno dostignemo nagrade, koji si obećao poniznima\n<i>po G. n.</i>","knRef":"Kniewald 1942, str. 539-540"},"9471a89f18398e23":{"kn":"Učini, Gospodine, ove darove pobožnoga puka, što ih stavljamo na Tvoje žrtvenike, zaslugom blaženoga Franje, sebi prijatnima, a po Tvome milosrđu nama spasonosnima,\n<i>po G. n.</i>","knRef":"Kniewald 1942, str. 540"},"6a327a2321e05499":{"kn":"Molimo Te, Gospodine, zagovorom blaženoga Franje, priznavaoca Tvoga, da nam nebeske tajne, što ih primismo, udijele pomoć i za vremeniti i vječni život,\n<i>po G. n.</i>","knRef":"Kniewald 1942, str. 540"}}});
